USE communityhub;
ALTER TABLE fivem_servers ADD COLUMN IF NOT EXISTS framework ENUM('standalone','qbcore') NOT NULL DEFAULT 'standalone';
ALTER TABLE fivem_servers ADD COLUMN IF NOT EXISTS connect_url VARCHAR(255) NULL;
ALTER TABLE fivem_servers ADD COLUMN IF NOT EXISTS restart_schedule VARCHAR(255) NULL;
ALTER TABLE fivem_servers ADD COLUMN IF NOT EXISTS is_enabled BOOLEAN NOT NULL DEFAULT TRUE;
CREATE TABLE IF NOT EXISTS fivem_announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,priority ENUM('info','important','critical') NOT NULL DEFAULT 'info',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT UNSIGNED NULL,expires_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS fivem_reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reporter_user_id BIGINT UNSIGNED NULL,server_id BIGINT UNSIGNED NULL,report_type VARCHAR(80) NOT NULL DEFAULT 'in_game',subject VARCHAR(160) NOT NULL,details TEXT NOT NULL,status ENUM('open','under_review','actioned','closed') NOT NULL DEFAULT 'open',assigned_to BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(reporter_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(server_id) REFERENCES fivem_servers(id) ON DELETE SET NULL,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS fivem_staff_actions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NOT NULL,target_user_id BIGINT UNSIGNED NULL,action_type VARCHAR(80) NOT NULL,reason TEXT NULL,server_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(server_id) REFERENCES fivem_servers(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_fivem_sessions_active ON fivem_player_sessions(server_id,left_at);
CREATE INDEX IF NOT EXISTS idx_patrol_user_time ON patrol_sessions(user_id,clocked_in_at);